const index = require("../../data/world/maps.index.json");

// Generated by `npm run maps:index` from frontend/public/maps (see docs/design/MAPS.md).
function getMap(id) {
	return Object.hasOwn(index, id) ? index[id] : null;
}

/** True if a client-claimed position is a free tile of a known map. */
function canStand(id, x, y) {
	const map = getMap(id);
	if (!map || !Number.isInteger(x) || !Number.isInteger(y)) return false;
	return x >= 0 && y >= 0 && x < map.width && y < map.height && map.collision[y][x] === "0";
}

module.exports = { getMap, canStand };
